1	/******************************************************************************
2	 * Copyright (c) 2024, Tri Dao.
3	 ******************************************************************************/
4	
5	// Include these 2 headers instead of torch/extension.h since we don't need all of the torch headers.
6	#pragma once
7	
8	#include <torch/nn/functional.h>
9	#include <ATen/cuda/CUDAContext.h>
10	#include <c10/cuda/CUDAGuard.h>
11	
12	#include <torch/extension.h>
13	
14	#include <cutlass/numeric_types.h>
15	
16	#include "include/flash.h"
17	#include "include/static_switch.h"
18	
19	#define CHECK_DEVICE(x) TORCH_CHECK(x.is_cuda(), #x " must be on CUDA")
20	#define CHECK_SHAPE(x, ...) TORCH_CHECK(x.sizes() == torch::IntArrayRef({__VA_ARGS__}), #x " must have shape (" #__VA_ARGS__ ")")
21	#define CHECK_CONTIGUOUS(x) TORCH_CHECK(x.is_contiguous(), #x " must be contiguous")
22	
23	void set_params_fprop(Flash_fwd_params &params,
24	                      // sizes
25	                      const size_t b,
26	                      const size_t seqlen_q,
27	                      const size_t seqlen_k,
28	                      const size_t seqlen_q_rounded,
29	                      const size_t seqlen_k_rounded,
30	                      const size_t h,
31	                      const size_t h_k,
32	                      const size_t d,
33	                      const size_t d_rounded,
34	                      // device pointers
35	                      const at::Tensor q,
36	                      const at::Tensor k, const at::Tensor k_pack, const at::Tensor k_params,
37	                      const at::Tensor v, const at::Tensor v_pack, const at::Tensor v_params,
38	                      at::Tensor out,
39	                      void *cu_seqlens_q_d,
40	                      void *cu_seqlens_k_d,
41	                      void *seqused_k,
42	                      void *p_d,
43	                      void *softmax_lse_d,
44	                      float p_dropout,
45	                      float softmax_scale,
46	                      int window_size_left,
47	                      int window_size_right,
48	                      const float softcap,
49	                      const std::string quant_mode,
50	                      const int group_size,
51	                      bool seqlenq_ngroups_swapped=false,
52	                      const bool unpadded_lse=false) {
53	
54	    // Reset the parameters
55	    params = {};
56	
57	    params.quant_mode = quant_mode;
58	    params.group_size = group_size;
59	    params.is_bf16 = q.dtype() == torch::kBFloat16;
60	
61	    params.q_ptr = q.data_ptr();
62	    // params.k_ptr = k.data_ptr();
63	    params.K_pack_ptr = k_pack.data_ptr();
64	    params.k_params_ptr = k_params.data_ptr();
65	    // params.v_ptr = v.data_ptr();
66	    params.v_pack_ptr = v_pack.data_ptr();
67	    params.v_params_ptr = v_params.data_ptr();
68	    // All stride are in elements, not bytes.
69	    params.q_row_stride = q.stride(-3);
70	    // params.k_row_stride = k.stride(-3);
71	    params.K_pack_row_stride = k_pack.stride(-3);
72	    params.k_params_row_stride = k_params.stride(-3);
73	    // params.v_row_stride = v.stride(-3);
74	    params.v_pack_row_stride = v_pack.stride(-3);
75	    params.v_params_row_stride = v_params.stride(-1);
76	
77	    params.k_params_dim_stride = k_params.stride(-1);
78	    params.v_params_dim_stride = v_params.stride(-3);
79	
80	    params.q_head_stride = q.stride(-2);
81	    // params.k_head_stride = k.stride(-2);
82	    params.K_pack_head_stride = k_pack.stride(-2);
83	    params.k_params_head_stride = k_params.stride(-2);
84	    // params.v_head_stride = v.stride(-2);
85	    params.v_pack_head_stride = v_pack.stride(-2);
86	    params.v_params_head_stride = v_params.stride(-2);
87	
88	    params.o_ptr = out.data_ptr();
89	    params.o_row_stride = out.stride(-3);
90	    params.o_head_stride = out.stride(-2);
91	
92	    if (cu_seqlens_q_d == nullptr) {
93	        params.q_batch_stride = q.stride(0);
94	        // params.k_batch_stride = k.stride(0);
95	        params.K_pack_batch_stride = k_pack.stride(0);
96	        params.k_params_batch_stride = k_params.stride(0);
97	        // params.v_batch_stride = v.stride(0);
98	        params.v_pack_batch_stride = v_pack.stride(0);
99	        params.v_params_batch_stride = v_params.stride(0);
100	        params.o_batch_stride = out.stride(0);
101	
102	        if (seqlenq_ngroups_swapped) {
103	            params.q_batch_stride *= seqlen_q;
104	            params.o_batch_stride *= seqlen_q;
105	        }
106	    }
107	
108	    params.cu_seqlens_q = static_cast<int *>(cu_seqlens_q_d);
109	    params.cu_seqlens_k = static_cast<int *>(cu_seqlens_k_d);
110	    params.seqused_k = static_cast<int *>(seqused_k);
111	
112	    // P = softmax(QK^T)
113	    params.p_ptr = p_d;
114	
115	    // Softmax sum
116	    params.softmax_lse_ptr = softmax_lse_d;
117	
118	    // Set the dimensions.
119	    params.b = b;
120	    params.h = h;
121	    params.h_k = h_k;
122	    params.h_h_k_ratio = h / h_k;
123	    params.seqlen_q = seqlen_q;
124	    params.seqlen_k = seqlen_k;
125	    params.seqlen_q_rounded = seqlen_q_rounded;
126	    params.seqlen_k_rounded = seqlen_k_rounded;
127	    params.d = d;
128	    params.d_rounded = d_rounded;
129	
130	    // Set the different scale values.
131	    #ifdef FLASHATTENTION_DISABLE_SOFTCAP
132	    TORCH_CHECK(softcap <= 0.0, "This flash attention build does not support softcap.");
133	    #endif
134	    if (softcap > 0.0) {
135	        params.softcap = softmax_scale / softcap;
136	        params.scale_softmax = softcap;
137	        params.scale_softmax_log2 = softcap * M_LOG2E;
138	    } else{
139	        // Remove potential NaN
140	        params.softcap = 0.0;
141	        params.scale_softmax = softmax_scale;
142	        params.scale_softmax_log2 = softmax_scale * M_LOG2E;
143	    }
144	
145	    // Set this to probability of keeping an element to simplify things.
146	    params.p_dropout = 1.f - p_dropout;
147	    // Convert p from float to int so we don't have to convert the random uint to float to compare.
148	    // [Minor] We want to round down since when we do the comparison we use <= instead of <
149	    // params.p_dropout_in_uint = uint32_t(std::floor(params.p_dropout * 4294967295.0));
150	    // params.p_dropout_in_uint16_t = uint16_t(std::floor(params.p_dropout * 65535.0));
151	    params.p_dropout_in_uint8_t = uint8_t(std::floor(params.p_dropout * 255.0));
152	    params.rp_dropout = 1.f / params.p_dropout;
153	    params.scale_softmax_rp_dropout = params.rp_dropout * params.scale_softmax;
154	    TORCH_CHECK(p_dropout < 1.f);
155	    #ifdef FLASHATTENTION_DISABLE_DROPOUT
156	    TORCH_CHECK(p_dropout == 0.0f, "This flash attention build does not support dropout.");
157	    #endif
158	
159	    // Causal is the special case where window_size_right == 0 and window_size_left < 0.
160	    // Local is the more general case where window_size_right >= 0 or window_size_left >= 0.
161	    params.is_causal = window_size_left < 0 && window_size_right == 0;
162	
163	    if (window_size_left < 0 && window_size_right >= 0) { window_size_left = seqlen_k; }
164	    if (window_size_left >= 0 && window_size_right < 0) { window_size_right = seqlen_k; }
165	    params.window_size_left = window_size_left;
166	    params.window_size_right = window_size_right;
167	
168	    #ifdef FLASHATTENTION_DISABLE_LOCAL
169	    TORCH_CHECK(params.is_causal || (window_size_left < 0 && window_size_right < 0),
170	    "This flash attention build does not support local attention.");
171	    #endif
172	
173	    params.is_seqlens_k_cumulative = true;
174	
175	    #ifdef FLASHATTENTION_DISABLE_UNEVEN_K
176	    TORCH_CHECK(d == d_rounded, "This flash attention build does not support headdim not being a multiple of 32.");
177	    #endif
178	
179	    params.unpadded_lse = unpadded_lse;
180	    params.seqlenq_ngroups_swapped = seqlenq_ngroups_swapped;
181	}
